import{_ as t,g as a,e as r,a4 as c}from"./chunks/framework.CEYJDsBW.js";const s=JSON.parse('{"title":"dev.dubhe.anvilcraft.block.fluid","description":"","frontmatter":{},"headers":[],"relativePath":"anvilcraft/21.1/api/dev-dubhe-anvilcraft-block-fluid.md","filePath":"anvilcraft/21.1/api/dev-dubhe-anvilcraft-block-fluid.md"}'),o={name:"anvilcraft/21.1/api/dev-dubhe-anvilcraft-block-fluid.md"};function l(d,e,b,i,n,v){return a(),r("div",null,[...e[0]||(e[0]=[c('<h1 id="dev-dubhe-anvilcraft-block-fluid" tabindex="-1">dev.dubhe.anvilcraft.block.fluid <a class="header-anchor" href="#dev-dubhe-anvilcraft-block-fluid" aria-label="Permalink to &quot;dev.dubhe.anvilcraft.block.fluid&quot;">​</a></h1><h2 id="controlvalveblock" tabindex="-1">ControlValveBlock <a class="header-anchor" href="#controlvalveblock" aria-label="Permalink to &quot;ControlValveBlock&quot;">​</a></h2><p><code>public class ControlValveBlock extends BetterBaseEntityBlock implements IHammerRemovable, IMoveableEntityBlock</code></p><p><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/ControlValveBlock.java#L46" target="_blank" rel="noreferrer">类型声明</a></p><p>控制阀（Control Valve），管道系统中的流体门控部件。 沿单一轴向（#AXIS X/Y/Z）连接管道，无前后方向之分。右键打开 GUI 设置允许通过的流体类型（白名单过滤）和最大流速。放置方式类似泵：贴在侧面的 直管/弯管会转为节点以正确吸附。</p><table tabindex="0"><thead><tr><th>成员签名</th><th>实现与调用约定</th><th>源码</th></tr></thead><tbody><tr><td><code>public static final MapCodec&lt;ControlValveBlock&gt; CODEC</code></td><td>初值 <code>simpleCodec(ControlValveBlock::new)</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/ControlValveBlock.java#L48" target="_blank" rel="noreferrer">字段</a></td></tr><tr><td><code>public static final EnumProperty&lt;Direction.Axis&gt; AXIS</code></td><td>初值 <code>BlockStateProperties.AXIS</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/ControlValveBlock.java#L49" target="_blank" rel="noreferrer">字段</a></td></tr><tr><td><code>public static final BooleanProperty POWERED</code></td><td>红石锁定：任意侧收到红石信号则锁定，流速视为 0 且 GUI 中不可调。<br>初值 <code>BlockStateProperties.POWERED</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/ControlValveBlock.java#L51" target="_blank" rel="noreferrer">字段</a></td></tr><tr><td><code>public ControlValveBlock(Properties properties)</code></td><td>实现调用 <code>super(properties)</code><br>实现调用 <code>registerDefaultState(stateDefinition.any().setValue(AXIS, Direction.Axis.Y).setValue(POWERED, false))</code><br>实现调用 <code>stateDefinition.any().setValue(AXIS, Direction.Axis.Y).setValue(POWERED, false)</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/ControlValveBlock.java#L57" target="_blank" rel="noreferrer">构造器</a></td></tr><tr><td><code>@Override public RenderShape getRenderShape(BlockState state)</code></td><td>客户端选择方块的渲染路径时调用。<br>末尾返回 <code>RenderShape.MODEL</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/ControlValveBlock.java#L72" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>@Override public VoxelShape getShape(BlockState state, BlockGetter level, BlockPos pos, CollisionContext ctx)</code></td><td>方块查询选取轮廓时调用。返回方块局部坐标中的 VoxelShape。<br>末尾返回 <code>switch (state.getValue(AXIS)) { case X -&gt; SHAPE_X; case Y -&gt; SHAPE_Y; default -&gt; SHAPE_Z; }</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/ControlValveBlock.java#L77" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>@Override @Nullable public BlockState getStateForPlacement(BlockPlaceContext context)</code></td><td>放置时沿点击面的轴向，并按周围红石初始化锁定状态。<br>放置方块时根据点击位置、朝向和相邻状态决定初始 BlockState。<br>末尾返回 <code>defaultBlockState() .setValue(AXIS, context.getClickedFace().getAxis()) .setValue(POWERED, powered)</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/ControlValveBlock.java#L87" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>public static boolean isConnectableFace(BlockState state, Direction faceToNeighbor)</code></td><td>判断控制阀在某面方向上是否为连接面（仅朝向轴两端）。<br><code>(!(state.getBlock() instanceof ControlValveBlock))</code> 成立时提前返回 <code>false</code><br>末尾返回 <code>faceToNeighbor.getAxis() == state.getValue(AXIS)</code><br><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/api/fluid/network/FluidNetworkScanner.java#L255" target="_blank" rel="noreferrer">调用处 FluidNetworkScanner.visitNeighborWithPhi</a></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/ControlValveBlock.java#L99" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>@Override public void setPlacedBy(Level level, BlockPos pos, BlockState state, @Nullable LivingEntity placer, ItemStack stack)</code></td><td>放置后将轴向上连接的直管/弯管转为节点，使其能正确吸附；并记录手轮朝向（面向玩家、垂直于轴的一面）。<br>实现调用 <code>super.setPlacedBy(level, pos, state, placer, stack)</code><br>实现调用 <code>level.getBlockEntity(pos)</code><br>实现调用 <code>be.setFacing(computeHandwheelFacing(state.getValue(AXIS), placer))</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/ControlValveBlock.java#L129" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>@Override public BlockState rotate(BlockState state, Rotation rotation)</code></td><td>实现调用 <code>state.getValue(AXIS)</code><br>实现调用 <code>state.setValue(AXIS, Direction.Axis.Z)</code><br>实现调用 <code>state.setValue(AXIS, Direction.Axis.X)</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/ControlValveBlock.java#L227" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>@Override public BlockState mirror(BlockState state, Mirror mirror)</code></td><td>末尾返回 <code>state</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/ControlValveBlock.java#L239" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>@Override public @Nullable ControlValveBlockEntity newBlockEntity(BlockPos pos, BlockState state)</code></td><td>为指定位置和状态创建方块实体。<br>末尾返回 <code>ModBlockEntities.CONTROL_VALVE.get().create(pos, state)</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/ControlValveBlock.java#L244" target="_blank" rel="noreferrer">方法</a></td></tr></tbody></table><h2 id="drainblock" tabindex="-1">DrainBlock <a class="header-anchor" href="#drainblock" aria-label="Permalink to &quot;DrainBlock&quot;">​</a></h2><p><code>public class DrainBlock extends BaseEntityBlock implements IHammerRemovable</code></p><p><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/DrainBlock.java#L28" target="_blank" rel="noreferrer">类型声明</a></p><p>排水口（Drain），管道系统的容器部件。内部 4B 流体容量，像储罐一样渲染内部流体， 并像机械动力软管滑轮一样向下把内部流体铺放到世界、或从上方抽取流体入内部。 逻辑见 DrainBlockEntity。</p><table tabindex="0"><thead><tr><th>成员签名</th><th>实现与调用约定</th><th>源码</th></tr></thead><tbody><tr><td><code>public static final MapCodec&lt;DrainBlock&gt; CODEC</code></td><td>初值 <code>simpleCodec(DrainBlock::new)</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/DrainBlock.java#L29" target="_blank" rel="noreferrer">字段</a></td></tr><tr><td><code>public DrainBlock(Properties properties)</code></td><td>执行 <code>super(properties)</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/DrainBlock.java#L31" target="_blank" rel="noreferrer">构造器</a></td></tr><tr><td><code>@Override public @Nullable BlockEntity newBlockEntity(BlockPos pos, BlockState state)</code></td><td>为指定位置和状态创建方块实体。<br>末尾返回 <code>ModBlockEntities.DRAIN.get().create(pos, state)</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/DrainBlock.java#L45" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>@Override public @Nullable &lt;T extends BlockEntity&gt; BlockEntityTicker&lt;T&gt; getTicker( Level level, BlockState state, BlockEntityType&lt;T&gt; type )</code></td><td><code>(level.isClientSide())</code> 成立时提前返回 <code>null</code><br>末尾返回 <code>createTickerHelper(type, ModBlockEntities.DRAIN.get(), DrainBlockEntity::tick)</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/DrainBlock.java#L50" target="_blank" rel="noreferrer">方法</a></td></tr></tbody></table><h2 id="pipeblock" tabindex="-1">PipeBlock <a class="header-anchor" href="#pipeblock" aria-label="Permalink to &quot;PipeBlock&quot;">​</a></h2><p><code>public abstract class PipeBlock extends Block implements SimpleWaterloggedBlock, IHammerRemovable, IHammerChangeable, EntityBlock, IMoveableEntityBlock</code></p><p><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeBlock.java#L73" target="_blank" rel="noreferrer">类型声明</a></p><p>管道系统抽象基类，定义了所有管道类型共用的方块状态属性、碰撞箱形状、 邻居检查工具方法和两个核心枚举。 子类： PipeStraightBlock — 直管，沿单一轴向延伸 PipeCornerBlock — 弯管，连接两个垂直方向 PipeNodeBlock — 节点，最多六个方向连接，可自动退化 管道连接规则： 管道 ↔ 管道：无端头（开放连接） 管道 ↔ IFluidHandler：有端头（封闭连接） 管道 ↔ 空气/其他：有端头</p><table tabindex="0"><thead><tr><th>成员签名</th><th>实现与调用约定</th><th>源码</th></tr></thead><tbody><tr><td><code>public static final EnumProperty&lt;Direction.Axis&gt; AXIS</code></td><td>直管的轴向（X / Y / Z）<br>初值 <code>BlockStateProperties.AXIS</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeBlock.java#L79" target="_blank" rel="noreferrer">字段</a></td></tr><tr><td><code>public static final EnumProperty&lt;CornerEnded&gt; CORNER_ENDED</code></td><td>弯管的拐角方向组合<br>初值 <code>EnumProperty.create(&quot;corner_ended&quot;, CornerEnded.class)</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeBlock.java#L83" target="_blank" rel="noreferrer">字段</a></td></tr><tr><td><code>public static final BooleanProperty HAS_END_START</code></td><td>第一端（直管负轴端/弯管 first 方向）是否有端头<br>初值 <code>BooleanProperty.create(&quot;has_end_start&quot;)</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeBlock.java#L87" target="_blank" rel="noreferrer">字段</a></td></tr><tr><td><code>public static final BooleanProperty HAS_END_END</code></td><td>第二端（直管正轴端/弯管 second 方向）是否有端头<br>初值 <code>BooleanProperty.create(&quot;has_end_end&quot;)</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeBlock.java#L91" target="_blank" rel="noreferrer">字段</a></td></tr><tr><td><code>public static final EnumProperty&lt;NodePipe&gt; DOWN</code></td><td>节点下方连接状态<br>初值 <code>EnumProperty.create(&quot;down&quot;, NodePipe.class)</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeBlock.java#L95" target="_blank" rel="noreferrer">字段</a></td></tr><tr><td><code>public static final EnumProperty&lt;NodePipe&gt; UP</code></td><td>节点上方连接状态<br>初值 <code>EnumProperty.create(&quot;up&quot;, NodePipe.class)</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeBlock.java#L99" target="_blank" rel="noreferrer">字段</a></td></tr><tr><td><code>public static final EnumProperty&lt;NodePipe&gt; NORTH</code></td><td>节点北向连接状态<br>初值 <code>EnumProperty.create(&quot;north&quot;, NodePipe.class)</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeBlock.java#L103" target="_blank" rel="noreferrer">字段</a></td></tr><tr><td><code>public static final EnumProperty&lt;NodePipe&gt; SOUTH</code></td><td>节点南向连接状态<br>初值 <code>EnumProperty.create(&quot;south&quot;, NodePipe.class)</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeBlock.java#L107" target="_blank" rel="noreferrer">字段</a></td></tr><tr><td><code>public static final EnumProperty&lt;NodePipe&gt; WEST</code></td><td>节点西向连接状态<br>初值 <code>EnumProperty.create(&quot;west&quot;, NodePipe.class)</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeBlock.java#L111" target="_blank" rel="noreferrer">字段</a></td></tr><tr><td><code>public static final EnumProperty&lt;NodePipe&gt; EAST</code></td><td>节点东向连接状态<br>初值 <code>EnumProperty.create(&quot;east&quot;, NodePipe.class)</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeBlock.java#L115" target="_blank" rel="noreferrer">字段</a></td></tr><tr><td><code>public static final BooleanProperty WATERLOGGED</code></td><td>是否含水<br>初值 <code>BlockStateProperties.WATERLOGGED</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeBlock.java#L119" target="_blank" rel="noreferrer">字段</a></td></tr><tr><td><code>public static final BooleanProperty HAS_CHECK_VALVE</code></td><td>本管道是否至少有一个面装了止逆阀。 止逆的方向数据不进 blockstate（否则节点 6 面 × 方向组合会爆炸），而是存进 PipeCheckValveBlockEntity；此布尔仅用于决定是否创建该 BE（true 才创建）， 因此每种管道 blockstate 只 ×2。<br>初值 <code>BooleanProperty.create(&quot;has_check_valve&quot;)</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeBlock.java#L128" target="_blank" rel="noreferrer">字段</a></td></tr><tr><td><code>public PipeBlock(Properties properties)</code></td><td>执行 <code>this(properties, false)</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeBlock.java#L225" target="_blank" rel="noreferrer">构造器</a></td></tr><tr><td><code>public PipeBlock(Properties properties, boolean glassPipe)</code></td><td>实现调用 <code>super(properties)</code><br>实现调用 <code>this.getStateDefinition().any() .setValue(WATERLOGGED, false) .setValue(HAS_CHECK_VALVE, false)</code><br>实现调用 <code>this.getStateDefinition().any() .setValue(WATERLOGGED, false)</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeBlock.java#L229" target="_blank" rel="noreferrer">构造器</a></td></tr><tr><td><code>public boolean isGlassPipe()</code></td><td>末尾返回 <code>this.glassPipe</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeBlock.java#L237" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>@Override @Nullable public BlockEntity newBlockEntity(BlockPos pos, BlockState state)</code></td><td>为指定位置和状态创建方块实体。<br><code>(this.glassPipe)</code> 成立时提前返回 <code>new GlassPipeBlockEntity(ModBlockEntities.GLASS_PIPE.get(), pos, state)</code><br>末尾返回 <code>state.getValue(HAS_CHECK_VALVE) ? new PipeCheckValveBlockEntity(ModBlockEntities.PIPE_CHECK_VALVE.get(), pos, state) : null</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeBlock.java#L249" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>@Nullable public static AbstractPipeCheckValveBlockEntity getCheckValve(Level level, BlockPos pos)</code></td><td>取该位置的止逆阀 BE（无则 null）。<br>末尾返回 <code>level.getBlockEntity(pos) instanceof AbstractPipeCheckValveBlockEntity be ? be : null</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeBlock.java#L261" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>public static Direction getDirectionFromAxis(Direction.Axis axis, Direction.AxisDirection axisDirection)</code></td><td>根据轴向和轴方向获取对应的 Direction。<br>参数 <code>axis</code> 轴向<br>参数 <code>axisDirection</code> 轴方向（NEGATIVE = 负方向，POSITIVE = 正方向）<br>返回 对应的方向（如 X+NEGATIVE → WEST）<br>末尾返回 <code>Direction.get(axisDirection, axis)</code><br><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/item/PipeBlockItem.java#L271" target="_blank" rel="noreferrer">调用处 PipeBlockItem.getConnectedBlockState</a></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeBlock.java#L273" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>public static EnumProperty&lt;NodePipe&gt; getPropertyForDirection(Direction direction)</code></td><td>获取指定方向对应的节点连接属性。<br>参数 <code>direction</code> 方向<br>返回 对应方向的 EnumProperty&amp;lt;NodePipe&amp;gt;<br>末尾返回 <code>switch (direction) { case DOWN -&gt; DOWN; case UP -&gt; UP; case NORTH -&gt; NORTH; case SOUTH -&gt; SOUTH; case WEST -&gt; WEST; case EAST -&gt; EAST; }</code><br><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/api/fluid/network/FluidNetworkScanner.java#L75" target="_blank" rel="noreferrer">调用处 FluidNetworkScanner.hasAnyConnectionToward</a></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeBlock.java#L283" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>public static boolean hasConnectionToward(BlockState state, Direction toward)</code></td><td>判断指定方块状态在给定方向上是否有管道臂/连接（不考虑端头是否可见）。 直管：方向与轴向相同即为有连接 弯管：方向为弯管两方向之一即为有连接 节点：该方向非 NodePipe#NONE 即为有连接<br>参数 <code>state</code> 方块状态<br>参数 <code>toward</code> 从此方块看向邻居的方向<br>返回 是否有管道臂/连接朝向该方向<br>实现调用 <code>state.getBlock()</code><br>实现调用 <code>toward.getAxis()</code><br>实现调用 <code>state.getValue(AXIS)</code><br><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/api/fluid/network/FluidNetworkScanner.java#L77" target="_blank" rel="noreferrer">调用处 FluidNetworkScanner.hasAnyConnectionToward</a></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeBlock.java#L306" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>public static boolean isNeighborPipeToward(Level level, BlockPos pos, Direction dir)</code></td><td>检查指定方向的邻居是否为管道且其连接朝向本方块。 用于判断本方块是否应与此邻居建立管道连接。<br>参数 <code>level</code> 世界<br>参数 <code>pos</code> 本方块位置<br>参数 <code>dir</code> 从此方块看向邻居的方向<br>返回 邻居管道是否朝向本方块<br>末尾返回 <code>neighborState.getBlock() instanceof PipeBlock &amp;&amp; hasConnectionToward(neighborState, dir.getOpposite())</code><br><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/item/PipeBlockItem.java#L266" target="_blank" rel="noreferrer">调用处 PipeBlockItem.getConnectedBlockState</a></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeBlock.java#L325" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>public static boolean isNeighborSameKindPipeToward(BlockState state, Level level, BlockPos pos, Direction dir)</code></td><td>检查指定方向的邻居是否为同类管道且其连接朝向本方块。 普通管道与玻璃管道互相连接时仍连通，但模型端头需要保留。<br>参数 <code>state</code> 本方块状态<br>参数 <code>level</code> 世界<br>参数 <code>pos</code> 本方块位置<br>参数 <code>dir</code> 从此方块看向邻居的方向<br>返回 邻居同类管道是否朝向本方块<br><code>(!(state.getBlock() instanceof PipeBlock pipe))</code> 成立时提前返回 <code>false</code><br>末尾返回 <code>neighborState.getBlock() instanceof PipeBlock neighborPipe &amp;&amp; pipe.isGlassPipe() == neighborPipe.isGlassPipe() &amp;&amp; hasConnectionToward(neighborState, dir.getOpposite())</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeBlock.java#L341" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>public static boolean isFluidHandler(Level level, BlockPos pos)</code></td><td>检查指定位置是否为流体处理器（通过 NeoForge Capability 系统）。<br>参数 <code>level</code> 世界<br>参数 <code>pos</code> 位置<br>返回 该位置是否提供 net.neoforged.neoforge.fluids.capability.IFluidHandler<br>末尾返回 <code>FluidContainerLookup.find(level, pos, null) != null</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeBlock.java#L359" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>public static boolean isFluidHandlerOrConnectablePump(Level level, BlockPos pos, Direction towardNeighbor)</code></td><td>检查指定位置是否为流体处理器（通过 NeoForge Capability 系统）， 或是连接面正对给定方向的泵。 泵仅在其连接面（朝向轴两端，即输入/输出端）正对 towardNeighbor 方向时才计入；垂直于朝向轴的实体侧面不算连接。<br>参数 <code>level</code> 世界<br>参数 <code>pos</code> 待检查的位置<br>参数 <code>towardNeighbor</code> 从该位置看向待连接邻居的方向<br>返回 该位置是否可在此方向形成流体连接<br><code>(state.getBlock() instanceof PumpBlock)</code> 成立时提前返回 <code>PumpBlock.isConnectableFace(state, towardNeighbor)</code><br><code>(state.getBlock() instanceof ControlValveBlock)</code> 成立时提前返回 <code>ControlValveBlock.isConnectableFace(state, towardNeighbor)</code><br>末尾返回 <code>FluidContainerLookup.find(level, pos, towardNeighbor) != null</code><br><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/item/PipeBlockItem.java#L100" target="_blank" rel="noreferrer">调用处 PipeBlockItem.tryConnectAdjacent</a></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeBlock.java#L375" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>public static boolean isNeighborOccupied(Level level, BlockPos pos, Direction dir)</code></td><td>检查指定方向的邻居是否被&quot;占用&quot;（有管道对准、是流体处理器、或连接面正对本方块的泵）。 用于判断管道端头是否应该打开（无端头连接）。<br>参数 <code>level</code> 世界<br>参数 <code>pos</code> 本方块位置<br>参数 <code>dir</code> 从此方块看向邻居的方向<br>返回 邻居是否占用该端<br><code>(isNeighborPipeToward(level, pos, dir))</code> 成立时提前返回 <code>true</code><br>末尾返回 <code>isFluidHandlerOrConnectablePump(level, pos.relative(dir), dir.getOpposite())</code><br><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/item/PipeBlockItem.java#L258" target="_blank" rel="noreferrer">调用处 PipeBlockItem.getConnectedBlockState</a></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeBlock.java#L395" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>@Override public Item asItem()</code></td><td>末尾返回 <code>this.glassPipe ? ModItems.GLASS_PIPE.get() : ModItems.PIPE.get()</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeBlock.java#L402" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>@Override public ItemStack getCloneItemStack( BlockState state, HitResult target, LevelReader level, BlockPos pos, Player player )</code></td><td><code>(this.glassPipe &amp;&amp; player.isCreative())</code> 成立时提前返回 <code>new ItemStack(ModItems.GLASS_PIPE.get())</code><br>末尾返回 <code>new ItemStack(ModItems.PIPE.get())</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeBlock.java#L407" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>public static BlockState straightVariant(BlockState state)</code></td><td>末尾返回 <code>(state.getBlock() instanceof PipeBlock pipe &amp;&amp; pipe.isGlassPipe() ? ModBlocks.GLASS_PIPE_STRAIGHT.get() : ModBlocks.PIPE_STRAIGHT.get()) .defaultBlockState()</code><br><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeNodeBlock.java#L268" target="_blank" rel="noreferrer">调用处 PipeNodeBlock.trySimplify</a></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeBlock.java#L421" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>public static BlockState cornerVariant(BlockState state)</code></td><td>末尾返回 <code>(state.getBlock() instanceof PipeBlock pipe &amp;&amp; pipe.isGlassPipe() ? ModBlocks.GLASS_PIPE_CORNER.get() : ModBlocks.PIPE_CORNER.get()) .defaultBlockState()</code><br><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeNodeBlock.java#L277" target="_blank" rel="noreferrer">调用处 PipeNodeBlock.trySimplify</a></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeBlock.java#L428" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>public static BlockState nodeVariant(BlockState state)</code></td><td>末尾返回 <code>(state.getBlock() instanceof PipeBlock pipe &amp;&amp; pipe.isGlassPipe() ? ModBlocks.GLASS_PIPE_NODE.get() : ModBlocks.PIPE_NODE.get()) .defaultBlockState()</code><br><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/ControlValveBlock.java#L158" target="_blank" rel="noreferrer">调用处 ControlValveBlock.convertPipeToNode</a></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeBlock.java#L435" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>@Nullable public static Direction getArmDirection(BlockPos pos, BlockHitResult hitResult)</code></td><td>根据精确点击坐标判断被点击的臂方向（中心体范围 [3,3,3]→[13,13,13]，超出即命中对应臂）。 点击在中心区域返回 null。所有管型共用同一判定（直管/弯管中心体略大也在此范围内）。<br>末尾返回 <code>armDir</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeBlock.java#L483" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>public boolean addCheckValve(Level level, BlockPos pos, BlockState state, Direction face, Direction flowOut)</code></td><td>在管道某个面添加止逆阀：把 HAS_CHECK_VALVE 置真（必要时替换方块以生成 BE）， 再写入该面的允许流出方向。仅服务端调用。<br>参数 <code>flowOut</code> 无红石信号时允许流出的世界方向<br>返回 是否成功添加<br><code>(level.isClientSide)</code> 成立时提前返回 <code>false</code><br><code>(be == null)</code> 成立时提前返回 <code>false</code><br>末尾返回 <code>true</code><br><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeBlock.java#L605" target="_blank" rel="noreferrer">调用处 PipeBlock.handleCheckValveInteraction</a></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeBlock.java#L520" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>public boolean removeCheckValve(Level level, BlockPos pos, BlockState state, Direction face)</code></td><td>移除管道某面的止逆阀；移除后若无任何面装阀则清除 HAS_CHECK_VALVE（销毁 BE）。 仅服务端调用。<br>返回 是否确实移除了一个阀<br><code>(level.isClientSide)</code> 成立时提前返回 <code>false</code><br><code>(be == null || !be.hasValveOn(face))</code> 成立时提前返回 <code>false</code><br>末尾返回 <code>true</code><br><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeBlock.java#L616" target="_blank" rel="noreferrer">调用处 PipeBlock.detachCheckValve</a></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeBlock.java#L544" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>public static void setBlockPreservingValve(Level level, BlockPos pos, BlockState oldState, BlockState newState)</code></td><td>跨管型转换时保留止逆阀数据：读取 oldPos 处旧 BE 的面映射，给 newState 打上 HAS_CHECK_VALVE 并在 setBlock 后回填到新 BE。 调用方应传入 尚未 setBlock 的目标 state ；本方法负责 setBlock 并返回， 保证形变（node↔straight↔corner）不丢失止逆阀。 客户端 同样保留止逆阀数据，避免依赖服务端同步即可获得即时视觉反馈。 服务端 额外对因管型变化而失去臂的面掉落止逆阀物品。<br>实现调用 <code>oldState.hasProperty(HAS_CHECK_VALVE)</code><br>实现调用 <code>oldState.getValue(HAS_CHECK_VALVE)</code><br>分支 <code>(oldState.hasProperty(HAS_CHECK_VALVE) &amp;&amp; oldState.getValue(HAS_CHECK_VALVE))</code> 内调用 <code>getCheckValve(level, pos)</code><br><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/item/PipeBlockItem.java#L154" target="_blank" rel="noreferrer">调用处 PipeBlockItem.modifyPipeToConnect</a></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeBlock.java#L707" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>@Override public FluidState getFluidState(BlockState state)</code></td><td>末尾返回 <code>state.getValue(WATERLOGGED) ? Fluids.WATER.getSource(false) : super.getFluidState(state)</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeBlock.java#L818" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>@Override public void onPlace(BlockState state, Level level, BlockPos pos, BlockState oldState, boolean movedByPiston)</code></td><td>管道部件放置 / 落地时使流体网络缓存失效（拓扑可能变化）。 子类覆写 onPlace 时须调用 super.onPlace(...)。<br>实现调用 <code>super.onPlace(state, level, pos, oldState, movedByPiston)</code><br>实现调用 <code>state.getValue(HAS_CHECK_VALVE)</code><br>实现调用 <code>level.getBlockEntity(pos)</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeBlock.java#L847" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>public VoxelShape getShape(BlockState state, Direction startDir, Direction endDir)</code></td><td>构建直管/弯管的碰撞箱：中心体 + 两端按端头状态拼接 arm。<br>参数 <code>state</code> 方块状态<br>参数 <code>startDir</code> 第一端方向<br>参数 <code>endDir</code> 第二端方向<br>返回 完整碰撞箱<br>末尾返回 <code>cachedShape(TWO_ARM_SHAPES, key, () -&gt; Shapes.or( PIPE_CENTER, endStart ? makeEnd(startDir) : makeNoEnd(startDir), endEnd ? makeEnd(endDir) : makeNoEnd(endDir) ))</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeBlock.java#L879" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>@Override public boolean checkBlockState(BlockState blockState)</code></td><td>末尾返回 <code>blockState.getBlock() instanceof PipeBlock pipe &amp;&amp; pipe.isGlassPipe()</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeBlock.java#L892" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>@Override public void notifyMoved(Level level, BlockPos pos, BlockState state, BlockEntity be)</code></td><td>分支 <code>(be instanceof GlassPipeBlockEntity glassPipe)</code> 内调用 <code>glassPipe.clearDisplay()</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeBlock.java#L897" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>@Override public boolean change(Player player, BlockPos blockPos, Level level, ItemStack anvilHammer)</code></td><td><code>(!(state.getBlock() instanceof PipeBlock pipe) || !pipe.isGlassPipe())</code> 成立时提前返回 <code>false</code><br>末尾返回 <code>true</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeBlock.java#L905" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>@Override public @Nullable Property&lt;?&gt; getChangeableProperty(BlockState blockState)</code></td><td>末尾返回 <code>null</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeBlock.java#L915" target="_blank" rel="noreferrer">方法</a></td></tr></tbody></table><h2 id="pipeblock-cornerended" tabindex="-1">PipeBlock.CornerEnded <a class="header-anchor" href="#pipeblock-cornerended" aria-label="Permalink to &quot;PipeBlock.CornerEnded&quot;">​</a></h2><p><code>public enum CornerEnded implements StringRepresentable</code></p><p><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeBlock.java#L926" target="_blank" rel="noreferrer">类型声明</a></p><p>弯管拐角方向枚举，表示管道在两个垂直方向之间的转弯。 命名规则：第一方向_第二方向（如 UP_NORTH = 上→北）。 HAS_END_START 控制第一方向的端头，HAS_END_END 控制第二方向。</p><table tabindex="0"><thead><tr><th>成员签名</th><th>实现与调用约定</th><th>源码</th></tr></thead><tbody><tr><td><code>DOWN_NORTH</code></td><td>下 → 北</td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeBlock.java#L930" target="_blank" rel="noreferrer">枚举值</a></td></tr><tr><td><code>DOWN_SOUTH</code></td><td>下 → 南</td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeBlock.java#L934" target="_blank" rel="noreferrer">枚举值</a></td></tr><tr><td><code>DOWN_WEST</code></td><td>下 → 西</td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeBlock.java#L938" target="_blank" rel="noreferrer">枚举值</a></td></tr><tr><td><code>DOWN_EAST</code></td><td>下 → 东</td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeBlock.java#L942" target="_blank" rel="noreferrer">枚举值</a></td></tr><tr><td><code>UP_NORTH</code></td><td>上 → 北</td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeBlock.java#L946" target="_blank" rel="noreferrer">枚举值</a></td></tr><tr><td><code>UP_SOUTH</code></td><td>上 → 南</td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeBlock.java#L950" target="_blank" rel="noreferrer">枚举值</a></td></tr><tr><td><code>UP_WEST</code></td><td>上 → 西</td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeBlock.java#L954" target="_blank" rel="noreferrer">枚举值</a></td></tr><tr><td><code>UP_EAST</code></td><td>上 → 东</td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeBlock.java#L958" target="_blank" rel="noreferrer">枚举值</a></td></tr><tr><td><code>NORTH_WEST</code></td><td>北 → 西</td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeBlock.java#L962" target="_blank" rel="noreferrer">枚举值</a></td></tr><tr><td><code>NORTH_EAST</code></td><td>北 → 东</td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeBlock.java#L966" target="_blank" rel="noreferrer">枚举值</a></td></tr><tr><td><code>SOUTH_WEST</code></td><td>南 → 西</td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeBlock.java#L970" target="_blank" rel="noreferrer">枚举值</a></td></tr><tr><td><code>SOUTH_EAST</code></td><td>南 → 东</td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeBlock.java#L974" target="_blank" rel="noreferrer">枚举值</a></td></tr><tr><td><code>public Direction getFirstDirection()</code></td><td>获取第一方向<br>返回 第一方向（受 PipeBlock#HAS_END_START 控制）<br>末尾返回 <code>this.first</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeBlock.java#L989" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>public Direction getSecondDirection()</code></td><td>获取第二方向<br>返回 第二方向（受 PipeBlock#HAS_END_END 控制）<br>末尾返回 <code>this.second</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeBlock.java#L998" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>public boolean containsDirection(Direction direction)</code></td><td>该弯管是否包含指定方向<br>返回 该弯管是否包含指定方向<br>末尾返回 <code>this.first == direction || this.second == direction</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeBlock.java#L1007" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>public static CornerEnded fromDirections(Direction a, Direction b)</code></td><td>根据两个方向查找匹配的弯管配置。顺序无关（a→b 和 b→a 均可匹配）。 无匹配时回退为 #UP_NORTH。<br>末尾返回 <code>UP_NORTH</code><br><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/item/PipeBlockItem.java#L283" target="_blank" rel="noreferrer">调用处 PipeBlockItem.getConnectedBlockState</a></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeBlock.java#L1015" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>@Override public String getSerializedName()</code></td><td>末尾返回 <code>this.name().toLowerCase(Locale.ROOT)</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeBlock.java#L1024" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>public static CornerEnded[] values()</code></td><td>返回按声明顺序排列的枚举常量数组，每次调用得到独立数组。</td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeBlock.java#L926" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>public static CornerEnded valueOf(String name)</code></td><td>按大小写精确匹配枚举名。未知名称抛出 IllegalArgumentException，null 抛出 NullPointerException。</td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeBlock.java#L926" target="_blank" rel="noreferrer">方法</a></td></tr></tbody></table><h2 id="pipeblock-nodepipe" tabindex="-1">PipeBlock.NodePipe <a class="header-anchor" href="#pipeblock-nodepipe" aria-label="Permalink to &quot;PipeBlock.NodePipe&quot;">​</a></h2><p><code>public enum NodePipe implements StringRepresentable</code></p><p><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeBlock.java#L1038" target="_blank" rel="noreferrer">类型声明</a></p><p>节点的单方向连接状态。 #PIPE — 无端头，连接至另一管道 #END — 有端头，连接至流体处理器 #NONE — 无臂，该方向无连接</p><table tabindex="0"><thead><tr><th>成员签名</th><th>实现与调用约定</th><th>源码</th></tr></thead><tbody><tr><td><code>PIPE</code></td><td>无端头开放连接（连至另一管道）</td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeBlock.java#L1042" target="_blank" rel="noreferrer">枚举值</a></td></tr><tr><td><code>END</code></td><td>有端头封闭连接（连至 IFluidHandler）</td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeBlock.java#L1046" target="_blank" rel="noreferrer">枚举值</a></td></tr><tr><td><code>NONE</code></td><td>无臂（该方向无连接）</td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeBlock.java#L1050" target="_blank" rel="noreferrer">枚举值</a></td></tr><tr><td><code>@Override public String getSerializedName()</code></td><td>末尾返回 <code>this.name().toLowerCase(Locale.ROOT)</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeBlock.java#L1052" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>public static NodePipe[] values()</code></td><td>返回按声明顺序排列的枚举常量数组，每次调用得到独立数组。</td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeBlock.java#L1038" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>public static NodePipe valueOf(String name)</code></td><td>按大小写精确匹配枚举名。未知名称抛出 IllegalArgumentException，null 抛出 NullPointerException。</td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeBlock.java#L1038" target="_blank" rel="noreferrer">方法</a></td></tr></tbody></table><h2 id="pipecornerblock" tabindex="-1">PipeCornerBlock <a class="header-anchor" href="#pipecornerblock" aria-label="Permalink to &quot;PipeCornerBlock&quot;">​</a></h2><p><code>public class PipeCornerBlock extends PipeBlock</code></p><p><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeCornerBlock.java#L23" target="_blank" rel="noreferrer">类型声明</a></p><p>弯管道，通过 PipeBlock#CORNER_ENDED 指定两个垂直方向的拐角。 两端各由 PipeBlock#HAS_END_START / PipeBlock#HAS_END_END 控制端头开关。当管道出现在非弯管方向的侧面时，自动转为 PipeNodeBlock。</p><table tabindex="0"><thead><tr><th>成员签名</th><th>实现与调用约定</th><th>源码</th></tr></thead><tbody><tr><td><code>public PipeCornerBlock(Properties properties)</code></td><td>构造弯管，默认上→北拐角，两端均有端头。<br>实现调用 <code>super(properties)</code><br>实现调用 <code>this.registerDefaultState()</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeCornerBlock.java#L28" target="_blank" rel="noreferrer">构造器</a></td></tr><tr><td><code>public PipeCornerBlock(Properties properties, boolean glassPipe)</code></td><td>实现调用 <code>super(properties, glassPipe)</code><br>实现调用 <code>this.registerDefaultState()</code><br><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/init/block/ModBlocks.java#L642" target="_blank" rel="noreferrer">调用处 ModBlocks</a></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeCornerBlock.java#L33" target="_blank" rel="noreferrer">构造器</a></td></tr><tr><td><code>@Override public VoxelShape getShape(BlockState state, BlockGetter level, BlockPos pos, CollisionContext ctx)</code></td><td>碰撞箱：中心体 + 两弯管方向按端头状态拼接 arm。<br>方块查询选取轮廓时调用。返回方块局部坐标中的 VoxelShape。<br>末尾返回 <code>this.getShape(state, startDir, endDir)</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeCornerBlock.java#L59" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>@Override public void onPlace(BlockState state, Level level, BlockPos pos, BlockState oldState, boolean movedByPiston)</code></td><td>放置 / 被推动落地时，按弯管两方向的实际邻居重算端头。 解决被活塞等整体推动后端头状态未刷新的问题。<br>实现调用 <code>super.onPlace(state, level, pos, oldState, movedByPiston)</code><br>实现调用 <code>state.is(oldState.getBlock())</code><br>实现调用 <code>oldState.getBlock()</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeCornerBlock.java#L131" target="_blank" rel="noreferrer">方法</a></td></tr></tbody></table><h2 id="pipenodeblock" tabindex="-1">PipeNodeBlock <a class="header-anchor" href="#pipenodeblock" aria-label="Permalink to &quot;PipeNodeBlock&quot;">​</a></h2><p><code>public class PipeNodeBlock extends PipeBlock</code></p><p><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeNodeBlock.java#L45" target="_blank" rel="noreferrer">类型声明</a></p><p>管道节点（多向连接器），最多支持六个方向的连接。 每个方向独立记录连接状态（PipeBlock.NodePipe）： PipeBlock.NodePipe#PIPE PIPE — 无端头，连接至同类管道 PipeBlock.NodePipe#END END — 有端头，连接至异类管道或 IFluidHandler PipeBlock.NodePipe#NONE NONE — 无臂，该方向无连接 节点支持 自动退化 ：当总连接数 ≤ 2 时自动简化为 PipeStraightBlock（对向）或 PipeCornerBlock（垂直）。 支持 扳手断开 ：用扳手右键点击节点的臂可断开 节点↔节点 或 节点↔IFluidHandler 的连接。</p><table tabindex="0"><thead><tr><th>成员签名</th><th>实现与调用约定</th><th>源码</th></tr></thead><tbody><tr><td><code>public PipeNodeBlock(Properties properties)</code></td><td>节点默认全方向无臂<br>实现调用 <code>super(properties)</code><br>实现调用 <code>this.registerDefaultState()</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeNodeBlock.java#L55" target="_blank" rel="noreferrer">构造器</a></td></tr><tr><td><code>public PipeNodeBlock(Properties properties, boolean glassPipe)</code></td><td>实现调用 <code>super(properties, glassPipe)</code><br>实现调用 <code>this.registerDefaultState()</code><br><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/init/block/ModBlocks.java#L652" target="_blank" rel="noreferrer">调用处 ModBlocks</a></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeNodeBlock.java#L60" target="_blank" rel="noreferrer">构造器</a></td></tr><tr><td><code>@Override public VoxelShape getShape(BlockState state, BlockGetter level, BlockPos pos, CollisionContext ctx)</code></td><td>碰撞箱：中心体 + 每个非 NONE 方向按状态拼接 arm（PIPE→noEnd, END→end）。<br>方块查询选取轮廓时调用。返回方块局部坐标中的 VoxelShape。<br>末尾返回 <code>cachedShape(SHAPES, shapeKey(state), () -&gt; buildShape(state))</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeNodeBlock.java#L93" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>@Override public void onPlace(BlockState state, Level level, BlockPos pos, BlockState oldState, boolean movedByPiston)</code></td><td>放置或从其他管型转换而来时，扫描全部六个方向并尝试退化。 仅在方块类型发生变化（非同类替换）时执行。<br>实现调用 <code>super.onPlace(state, level, pos, oldState, movedByPiston)</code><br>实现调用 <code>state.is(oldState.getBlock())</code><br>实现调用 <code>oldState.getBlock()</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeNodeBlock.java#L124" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>public static NodePipe evaluateNeighbor(Level level, BlockPos pos, Direction dir)</code></td><td>评估指定方向邻居的连接状态。 邻居是同类管道且对准本节点 → NodePipe#PIPE 邻居是异类管道、IFluidHandler 或 PumpBlock → NodePipe#END 其他 → NodePipe#NONE<br>参数 <code>level</code> 世界<br>参数 <code>pos</code> 本节点位置<br>参数 <code>dir</code> 评估方向<br>返回 该方向应设置的连接状态<br>末尾返回 <code>evaluateNeighbor(level, pos, level.getBlockState(pos), dir)</code><br><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/ControlValveBlock.java#L163" target="_blank" rel="noreferrer">调用处 ControlValveBlock.convertPipeToNode</a></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeNodeBlock.java#L193" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>public static NodePipe evaluateNeighbor(Level level, BlockPos pos, BlockState state, Direction dir)</code></td><td><code>(neighborState.getBlock() instanceof PumpBlock)</code> 成立时提前返回 <code>PumpBlock.isConnectableFace(neighborState, dir.getOpposite()) ? NodePipe.END : NodePipe.NONE</code><br><code>(neighborState.getBlock() instanceof ControlValveBlock)</code> 成立时提前返回 <code>ControlValveBlock.isConnectableFace(neighborState, dir.getOpposite()) ? NodePipe.END : NodePipe.NONE</code><br><code>(isFluidHandler(level, neighborPos))</code> 成立时提前返回 <code>NodePipe.END</code><br>末尾返回 <code>NodePipe.NONE</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeNodeBlock.java#L197" target="_blank" rel="noreferrer">方法</a></td></tr></tbody></table><h2 id="pipestraightblock" tabindex="-1">PipeStraightBlock <a class="header-anchor" href="#pipestraightblock" aria-label="Permalink to &quot;PipeStraightBlock&quot;">​</a></h2><p><code>public class PipeStraightBlock extends PipeBlock</code></p><p><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeStraightBlock.java#L33" target="_blank" rel="noreferrer">类型声明</a></p><p>直管道，沿单一轴向（PipeBlock#AXIS X/Y/Z）延伸。 两端通过 PipeBlock#HAS_END_START / PipeBlock#HAS_END_END 控制端头开关： true — 有端头（封闭） false — 无端头（开放，连接至管道） 当管道出现在侧面（垂直方向）时，自动转为 PipeNodeBlock，由节点的 onPlace+trySimplify 决定最终形态（弯管或节点）。</p><table tabindex="0"><thead><tr><th>成员签名</th><th>实现与调用约定</th><th>源码</th></tr></thead><tbody><tr><td><code>public PipeStraightBlock(Properties properties)</code></td><td>构造直管，默认沿 X 轴，两端均有端头。<br>实现调用 <code>super(properties)</code><br>实现调用 <code>this.registerDefaultState()</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeStraightBlock.java#L38" target="_blank" rel="noreferrer">构造器</a></td></tr><tr><td><code>public PipeStraightBlock(Properties properties, boolean glassPipe)</code></td><td>实现调用 <code>super(properties, glassPipe)</code><br>实现调用 <code>this.registerDefaultState()</code><br><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/init/block/ModBlocks.java#L632" target="_blank" rel="noreferrer">调用处 ModBlocks</a></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeStraightBlock.java#L43" target="_blank" rel="noreferrer">构造器</a></td></tr><tr><td><code>@Override @Nullable public BlockState getStateForPlacement(BlockPlaceContext context)</code></td><td>放置时沿点击面的轴向放置。<br>放置方块时根据点击位置、朝向和相邻状态决定初始 BlockState。<br>实现调用 <code>this.defaultBlockState() .setValue(AXIS, context.getClickedFace().getAxis())</code><br>实现调用 <code>this.defaultBlockState()</code><br>实现调用 <code>context.getClickedFace().getAxis()</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeStraightBlock.java#L69" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>@Override public VoxelShape getShape(BlockState state, BlockGetter level, BlockPos pos, CollisionContext ctx)</code></td><td>碰撞箱：中心体 + 两端按端头状态拼接 noEnd 或 end arm。<br>方块查询选取轮廓时调用。返回方块局部坐标中的 VoxelShape。<br>末尾返回 <code>this.getShape(state, startDir, endDir)</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeStraightBlock.java#L80" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>@Override public void onPlace(BlockState state, Level level, BlockPos pos, BlockState oldState, boolean movedByPiston)</code></td><td>放置 / 被推动落地时，按两端实际邻居重算端头（端头 = 该端未接对准的管道）。 解决被活塞等整体推动后端头状态未刷新的问题。<br>实现调用 <code>super.onPlace(state, level, pos, oldState, movedByPiston)</code><br>实现调用 <code>state.is(oldState.getBlock())</code><br>实现调用 <code>oldState.getBlock()</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PipeStraightBlock.java#L156" target="_blank" rel="noreferrer">方法</a></td></tr></tbody></table><h2 id="pumpblock" tabindex="-1">PumpBlock <a class="header-anchor" href="#pumpblock" aria-label="Permalink to &quot;PumpBlock&quot;">​</a></h2><p><code>public class PumpBlock extends BetterBaseEntityBlock implements IHammerRemovable, IHammerChangeable, IMoveableEntityBlock</code></p><p><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PumpBlock.java#L44" target="_blank" rel="noreferrer">类型声明</a></p><p>泵（Pump），管道系统的主动流体输送设备。 消耗 32kW 电力，输入端等效高度 +10，输出端 -10。 12 向放置（Orientation），铁砧锤右键反转方向，红石可关闭。</p><table tabindex="0"><thead><tr><th>成员签名</th><th>实现与调用约定</th><th>源码</th></tr></thead><tbody><tr><td><code>public static final EnumProperty&lt;Orientation&gt; ORIENTATION</code></td><td>初值 <code>EnumProperty.create(&quot;orientation&quot;, Orientation.class)</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PumpBlock.java#L45" target="_blank" rel="noreferrer">字段</a></td></tr><tr><td><code>public static final BooleanProperty POWERED</code></td><td>初值 <code>BlockStateProperties.POWERED</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PumpBlock.java#L46" target="_blank" rel="noreferrer">字段</a></td></tr><tr><td><code>public static final BooleanProperty OVERLOAD</code></td><td>初值 <code>IPowerComponent.OVERLOAD</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PumpBlock.java#L47" target="_blank" rel="noreferrer">字段</a></td></tr><tr><td><code>public PumpBlock(Properties properties)</code></td><td>实现调用 <code>super(properties)</code><br>实现调用 <code>stateDefinition.any() .setValue(ORIENTATION, Orientation.NORTH_UP) .setValue(POWERED, false)</code><br>实现调用 <code>stateDefinition.any() .setValue(ORIENTATION, Orientation.NORTH_UP)</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PumpBlock.java#L62" target="_blank" rel="noreferrer">构造器</a></td></tr><tr><td><code>@Override public RenderShape getRenderShape(BlockState state)</code></td><td>客户端选择方块的渲染路径时调用。<br>末尾返回 <code>RenderShape.MODEL</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PumpBlock.java#L75" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>@Override public VoxelShape getShape(BlockState state, BlockGetter level, BlockPos pos, CollisionContext ctx)</code></td><td>根据朝向返回旋转后的主体碰撞箱<br>方块查询选取轮廓时调用。返回方块局部坐标中的 VoxelShape。<br>末尾返回 <code>switch (state.getValue(ORIENTATION).getDirection().getAxis()) { case X -&gt; SHAPE_X; case Y -&gt; SHAPE_Y; default -&gt; SHAPE_Z; }</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PumpBlock.java#L83" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>@Override @Nullable public BlockState getStateForPlacement(BlockPlaceContext context)</code></td><td>放置时根据玩家视线和 Shift 计算朝向。 水平摆放：默认输出端朝向目标方块，Shift 反向（输出端指向玩家） 垂直摆放：默认输出端朝向上方/下方，Shift 反转垂直方向（UP ↔ DOWN）<br>放置方块时根据点击位置、朝向和相邻状态决定初始 BlockState。<br>末尾返回 <code>defaultBlockState() .setValue(ORIENTATION, orientation) .setValue(POWERED, context.getLevel().hasNeighborSignal(context.getClickedPos()))</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PumpBlock.java#L104" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>public static boolean isConnectableFace(BlockState pumpState, Direction faceToNeighbor)</code></td><td>判断泵是否在指定面方向上与邻居形成流体连接。 泵的模型为沿朝向轴延伸的管体，仅有朝向轴两端（输入端 / 输出端）开口， 垂直于朝向轴的面为实体面，不连接流体。<br>参数 <code>pumpState</code> 泵的方块状态<br>参数 <code>faceToNeighbor</code> 从泵看向邻居的方向<br>返回 该面是否为泵的连接面（输入端或输出端）<br><code>(!(pumpState.getBlock() instanceof PumpBlock))</code> 成立时提前返回 <code>false</code><br>末尾返回 <code>faceToNeighbor.getAxis() == pumpState.getValue(ORIENTATION).getDirection().getAxis()</code><br><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/api/fluid/network/FluidNetworkScanner.java#L85" target="_blank" rel="noreferrer">调用处 FluidNetworkScanner.isConnectablePump</a></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PumpBlock.java#L160" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>@Override public void setPlacedBy(Level level, BlockPos pos, BlockState state, @Nullable LivingEntity placer, ItemStack stack)</code></td><td>放置后将朝向轴上连接的直管/弯管转为三通节点，使其能正确吸附管道。 仅处理泵的连接面（输入端 / 输出端），垂直于朝向轴的侧面不形成连接。<br>实现调用 <code>super.setPlacedBy(level, pos, state, placer, stack)</code><br>实现调用 <code>Direction.values()</code><br>实现调用 <code>isConnectableFace(state, dir)</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PumpBlock.java#L171" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>@Override public void neighborChanged(BlockState state, Level level, BlockPos pos, Block block, BlockPos fromPos, boolean isMoving)</code></td><td>红石信号更新<br>实现调用 <code>FluidNetworkManager.INSTANCE.addAdjacentContainers(level, pos)</code><br>实现调用 <code>level.hasNeighborSignal(pos)</code><br>实现调用 <code>state.getValue(POWERED)</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PumpBlock.java#L217" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>@Override public boolean change(Player player, BlockPos blockPos, Level level, ItemStack anvilHammer)</code></td><td>铁砧锤反转方向<br>末尾返回 <code>true</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PumpBlock.java#L249" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>@Override public @Nullable Property&lt;?&gt; getChangeableProperty(BlockState state)</code></td><td>末尾返回 <code>ORIENTATION</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PumpBlock.java#L256" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>@Override public BlockState rotate(BlockState state, Rotation rotation)</code></td><td>末尾返回 <code>state.setValue(ORIENTATION, state.getValue(ORIENTATION).rotate(rotation))</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PumpBlock.java#L261" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>@Override public BlockState mirror(BlockState state, Mirror mirror)</code></td><td>末尾返回 <code>state.setValue(ORIENTATION, state.getValue(ORIENTATION).mirror(mirror))</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PumpBlock.java#L266" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>@Override public @Nullable PumpBlockEntity newBlockEntity(BlockPos pos, BlockState state)</code></td><td>为指定位置和状态创建方块实体。<br>末尾返回 <code>ModBlockEntities.PUMP.get().create(pos, state)</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PumpBlock.java#L271" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>@Override @Nullable public &lt;T extends BlockEntity&gt; BlockEntityTicker&lt;T&gt; getTicker(Level level, BlockState state, BlockEntityType&lt;T&gt; type)</code></td><td><code>(level.isClientSide())</code> 成立时提前返回 <code>null</code><br>末尾返回 <code>BaseEntityBlock.createTickerHelper(type, ModBlockEntities.PUMP.get(), PumpBlockEntity::tick)</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PumpBlock.java#L276" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>@Override public boolean checkBlockState(BlockState blockState)</code></td><td>末尾返回 <code>true</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/block/fluid/PumpBlock.java#L283" target="_blank" rel="noreferrer">方法</a></td></tr></tbody></table>',46)])])}const p=t(o,[["render",l]]);export{s as __pageData,p as default};
